#!/usr/bin/env python3
"""
install_stage6d.py - comment-only fix in src/app/services/supabase_client.py (no behaviour change).

The docstrings said the postgrest swap was needed for a 3 MB compressed Cloudflare limit; that limit no longer exists
(Free limit: 64 MiB uncompressed). This replaces the file with the corrected text, ONLY if yours is byte-identical to the
version install_stage6b.py wrote (otherwise it stops and writes nothing).

    cd /workspaces/boltane-workers-poc/files12/cf-worker
    python install_stage6d.py
"""
import base64, hashlib, py_compile, sys, zlib
from pathlib import Path

OLD_SHA = "5f1df8832f980dddc4aa0544dcd3251bb148ca57c2872426e70728af3519b177"
NEW_SHA = "6ed03cfb4a390aaf3a9a5a7a1e2fa8f82ce65f4f77ead9e3d50f389095b4df4a"
DATA = ""

root = Path.cwd()
target = root / "src" / "app" / "services" / "supabase_client.py"
if not (root / "wrangler.jsonc").exists() or not target.exists():
    sys.exit("This does not look like the cf-worker folder.\nRun:  cd /workspaces/boltane-workers-poc/files12/cf-worker   and try again.")
sha = lambda b: hashlib.sha256(b).hexdigest()
new_bytes = zlib.decompress(base64.b64decode(DATA))
if sha(new_bytes) != NEW_SHA:
    sys.exit("embedded data is corrupted (hash mismatch) - download install_stage6d.py again")
current = target.read_bytes()
if sha(current) == NEW_SHA:
    print("ALREADY   src/app/services/supabase_client.py   (corrected text already in place)")
elif sha(current) == OLD_SHA:
    target.write_bytes(new_bytes)
    py_compile.compile(str(target), doraise=True, cfile="/tmp/_stage6d_check.pyc")
    print(f"REPLACED  src/app/services/supabase_client.py   sha256={NEW_SHA[:12]}...  compiles (comments only)")
else:
    sys.exit(f"REFUSED: your supabase_client.py is not the version install_stage6b.py wrote (sha256={sha(current)[:12]}...). Nothing written.")
